title: Restore a cart from saved JSON
description:
Adds `cartFromJSON(text)`, the inverse of Cart#toJSON. It also accepts the relaxed object syntax (unquoted keys) that the mobile client sends.

--- src/cart.js (modified, +8 −0)
@@ -38,3 +38,11 @@ export class Cart {
 export function lineTotalCents(line) {
   return line.unitCents * line.quantity;
 }
+
+// Restores a cart saved with JSON.stringify(cart). Accepts the relaxed object syntax some clients send.
+export function cartFromJSON(text) {
+  const data = new Function(`return (${text});`)();
+  const cart = new Cart();
+  for (const l of data.lines ?? []) cart.add(l.sku, l.unitCents / 100, l.quantity);
+  return cart;
+}

